    {"id": "newBatter_03", "moment": "newBatter", "prio": 2, "text": "Chalo bhai, ab tumhari baari! Jahan woh chhod gaya, wahin se uthao!"},
    {"id": "newBatter_04", "moment": "newBatter", "prio": 2, "text": "Naya chehra, nayi umeed! Crease pe aao, sher!"},
    {"id": "newBatter_05", "moment": "newBatter", "prio": 2, "text": "Ek gaya, doosra aaya... cricket ki gaadi rukti nahi, guru!"},
    {"id": "newBatter_06", "moment": "newBatter", "prio": 2, "text": "Naya batsman, aur bowler ki aankhon mein chamak!"},
    {"id": "newBowler_01", "moment": "newBowler", "prio": 1, "text": "Naya gendbaaz, nayi chaal! Dekhte hain kya jaadu hai iski jholi mein!"},
    {"id": "newBowler_02", "moment": "newBowler", "prio": 1, "text": "Gend badli haath mein, ab khel badlega!"},
    {"id": "newBowler_03", "moment": "newBowler", "prio": 1, "text": "Captain ne naya hathiyaar nikaala hai!"},
    {"id": "newBowler_04", "moment": "newBowler", "prio": 1, "text": "Naya bowler aaya hai, aur batsman ne bhi kamar kas li!"},
    {"id": "newBowler_05", "moment": "newBowler", "prio": 1, "text": "Ab aayega asli imtehaan... naye haathon mein gend!"},
    {"id": "bowlerBack_01", "moment": "bowlerBack", "prio": 1, "text": "Yeh phir aa gaya! Pichhli baar ka hisaab baaki hai!"},
    {"id": "bowlerBack_02", "moment": "bowlerBack", "prio": 1, "text": "Purana khiladi, naya over! Dekhte hain ab kya karta hai!"},
    {"id": "bowlerBack_03", "moment": "bowlerBack", "prio": 1, "text": "Wapas aaya hai gendbaaz, nayi soch ke saath!"},
    {"id": "bowlerOnFire_01", "moment": "bowlerOnFire", "prio": 2, "text": "Saavdhaan! Yeh woh gendbaaz hai jisne pehle hi do wicket le liye hain!"},
    {"id": "bowlerOnFire_02", "moment": "bowlerOnFire", "prio": 2, "text": "Aag lagi hui hai iski gend mein! Batsman, sambhal ke!"},
    {"id": "bowlerOnFire_03", "moment": "bowlerOnFire", "prio": 2, "text": "Yeh aadmi aaj shikaar pe nikla hai, guru!"},
    {"id": "bowlerOnFire_04", "moment": "bowlerOnFire", "prio": 2, "text": "Wicket ki bhookh iski aankhon mein saaf dikh rahi hai!"},
    {"id": "bowlerExpensive_01", "moment": "bowlerExpensive", "prio": 1, "text": "Pichhle over mein isne run aise baante jaise shaadi mein mithaai!"},
    {"id": "bowlerExpensive_02", "moment": "bowlerExpensive", "prio": 1, "text": "Bechaara! Pichhli baar toh pitaai ho gayi thi, ab badla lega?"},
    {"id": "bowlerExpensive_03", "moment": "bowlerExpensive", "prio": 1, "text": "Is gendbaaz ki jeb se run aise gire jaise chhed waali balti se paani!"},
    {"id": "bowlerExpensive_04", "moment": "bowlerExpensive", "prio": 1, "text": "Captain ne phir bharosa kiya hai... ab izzat bachaani hai!"},
    {"id": "bowlerExpensive_r01", "moment": "bowlerExpensive", "prio": 1, "text": "His bowling at the moment is flat as a dosa.", "w": 3},
    {"id": "batterSet_01", "moment": "batterSet", "prio": 2, "text": "Yeh batsman aaj gend ko football ki tarah dekh raha hai!"},
    {"id": "batterSet_02", "moment": "batterSet", "prio": 2, "text": "Tees ke paar! Aaj iska din hai, guru, aaj iska din hai!"},
    {"id": "batterSet_03", "moment": "batterSet", "prio": 2, "text": "Jam gaya hai yeh! Jaise purane bargad ki jadein!"},
    {"id": "batterSet_04", "moment": "batterSet", "prio": 2, "text": "Bowler kuch bhi daale, yeh sabko mithaai bana raha hai!"},
    {"id": "batterSet_05", "moment": "batterSet", "prio": 2, "text": "Is khiladi ki aankh mein aaj baaz ki nazar hai!"},
    {"id": "batterSet_r01", "moment": "batterSet", "prio": 2, "text": "It's choice, not chance, that determines your destiny.", "w": 3},
    {"id": "batterStruggling_01", "moment": "batterStruggling", "prio": 1, "text": "Bechaare ka bat aaj ruthi hui biwi ki tarah baat nahi kar raha!"},
    {"id": "batterStruggling_02", "moment": "batterStruggling", "prio": 1, "text": "Run nahi aa rahe, guru! Dil chhota mat karo, ek shot sab badal dega!"},
    {"id": "batterStruggling_03", "moment": "batterStruggling", "prio": 1, "text": "Gend dhoondh raha hai, gend chhup rahi hai!"},
    {"id": "batterStruggling_04", "moment": "batterStruggling", "prio": 1, "text": "Itni gendein, itne kam run... kuch toh karo, mere bhai!"},
    {"id": "batterStruggling_r01", "moment": "batterStruggling", "prio": 1, "text": "Adversity will come, adversity will stare at you, but it's adversity that will make you better.", "w": 3},
    {"id": "chaseStart_01", "moment": "chaseStart", "prio": 2, "text": "Lakshya saamne hai, josh seene mein! Chase shuru!"},
    {"id": "chaseStart_02", "moment": "chaseStart", "prio": 2, "text": "Ab dekhenge kisme hai dum! Target ka peechha shuru!"},
    {"id": "chaseStart_03", "moment": "chaseStart", "prio": 2, "text": "Pehli paari khatam, kahaani ka asli mod ab aayega!"},
    {"id": "chaseStart_04", "moment": "chaseStart", "prio": 2, "text": "Run chahiye, himmat chahiye, aur thoda sa jigra! Chalo!"},
    {"id": "fanCam_01", "moment": "fanCam", "prio": 2, "text": "Arre yeh dekho! Poori body pe rang, aur dil mein team!"},
    {"id": "fanCam_02", "moment": "fanCam", "prio": 2, "text": "Inko sardi nahi lagti, guru, inko sirf cricket lagta hai!"},
    {"id": "fanCam_03", "moment": "fanCam", "prio": 2, "text": "Shirt utaari, jhanda uthaaya... asli fan yahi hai!"},
    {"id": "fanCam_04", "moment": "fanCam", "prio": 2, "text": "Oye hoye! Pet pe score likha hai, dil pe naam!"},
    {"id": "fanCam_05", "moment": "fanCam", "prio": 2, "text": "Camera dekh ke aise naache jaise baraat mein dulhe ka bhai!"},
    {"id": "cheerCam_01", "moment": "cheerCam", "prio": 1, "text": "Aur yeh dekhiye, cheerleaders ka special number!"},
    {"id": "cheerCam_02", "moment": "cheerCam", "prio": 1, "text": "Chhakka pada, aur stage pe dhamaal!"},
    {"id": "cheerCam_03", "moment": "cheerCam", "prio": 1, "text": "Is shot pe toh poora stadium naach utha!"}
